fill: #fca5a5;\n  text-anchor: middle;\n  dominant-baseline: middle;\n}\n\n/* 灵装绝技机制卡 */\n.noble-art-block {\n  margin-top: 10px;\n  padding: 10px 12px;\n  border-radius: 10px;\n  background: var(--card2);\n  border-left: 3px solid var(--crimson);\n}\n.noble-art-title {\n  font-size: 13px;\n  font-weight: 700;\n  color: var(--ink);\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n.noble-art-desc {\n  font-size: 12px;\n  color: var(--ink2);\n  margin-top: 4px;\n  line-height: 1.5;\n}\n\n/* 同伴名册与羁绊列表 */\n.roster-list {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  padding: 0 14px;\n}\n.roster-card {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 10px 12px;\n  background: var(--card);\n  border-radius: 14px;\n  border: 1px solid var(--hair);\n  cursor: pointer;\n}\n.roster-card:hover { background: var(--press); }\n.roster-ava {\n  width: 40px;\n  height: 40px;\n  border-radius: 10px;\n  background: linear-gradient(135deg, #38bdf8 0%, #0284c7 100%);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-weight: 700;\n  color: #fff;\n  flex: none;\n}\n.roster-info { flex: 1; min-width: 0; overflow-wrap: anywhere; }\n.roster-name-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n.roster-name { font-size: 13.5px; font-weight: 700; }\n.roster-rank {\n  font-size: 10px;\n  font-weight: 800;\n  padding: 1px 5px;\n  border-radius: 4px;\n  background: rgba(239, 68, 68, 0.2);\n  color: #fca5a5;\n}\n.roster-device {\n  font-size: 11px;\n  color: var(--muted);\n  margin-top: 2px;\n}\n\n/* 破军 LIME 聊天 */\n.lime-threads {\n  display: flex;\n  flex-direction: column;\n}\n.lime-row {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 12px 14px;\n  border-bottom: 1px solid var(--hair);\n  cursor: pointer;\n}\n.lime-row:hover { background: var(--press); }\n.lime-avatar {\n  width: 44px;\n  height: 44px;\n  border-radius: 14px;\n  background: var(--card2);\n  display: flex;\n  align-items: