}\n\n#blazer-body.gba-status .card-avatar {\n  background: var(--gba-gold);\n  color: var(--gba-ink);\n  border: 2px solid var(--gba-ink);\n  box-shadow: none;\n}\n\n#blazer-body.gba-status .card-rank-badge {\n  display: inline-block;\n  vertical-align: middle;\n  min-width: 27px;\n  margin-left: 3px;\n  padding: 2px 5px;\n  border: 2px solid var(--gba-ink);\n  border-radius: 0;\n  background: var(--gba-gold);\n  color: var(--gba-ink);\n  font: 700 13px/1.3 var(--font-num);\n  text-align: center;\n  text-shadow: none;\n  white-space: nowrap;\n}\n\n/* 觉醒是独立布尔状态，使用文字和边框区分，不伪装成等级奖励。 */\n#blazer-body.gba-status .gba-awakening {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  margin: 10px 0;\n  padding: 7px 9px;\n  border: 1px solid #82908f;\n  background: var(--gba-paper-shade);\n  color: var(--gba-muted);\n  font-size: 12px;\n}\n\n#blazer-body.gba-status .gba-awakening strong {\n  color: var(--gba-ink);\n  font-weight: 700;\n}\n\n#blazer-body.gba-status .gba-awakening[data-awakened='true'] {\n  border-left: 4px solid var(--gba-red);\n}\n\n/* A navy field keeps the chart distinct from the paper explanation beneath it. */\n#blazer-body.gba-status .radar-container {\n  background: var(--gba-navy);\n  border: 2px solid var(--gba-ink);\n  padding: 12px 0;\n  min-width: 0;\n}\n\n#blazer-body.gba-status .radar-svg {\n  display: block;\n  width: min(100%, 320px);\n  max-height: none;\n  height: auto;\n  overflow: visible;\n}\n\n#blazer-body.gba-status .radar-web,\n#blazer-body.gba-status .radar-web-spoke,\n#blazer-body.gba-status .radar-spoke {\n  stroke: #91abc0;\n  stroke-width: 1;\n  stroke-opacity: .7;\n}\n\n#blazer-body.gba-status .radar-web { fill: none; }\n\n#blazer-body.gba-status .radar-polygon {\n  fill: var(--gba-teal);\n  fill-opacity: .72;\n  stroke: var(--gba-gold);\n  stroke-width: 2.2;\n  filter: none;\n}\n\n#blazer-body.gba-status .radar-point {\n  fill: var(--gba-paper);\n  stroke: var(--gba-ink);\n  stroke-width: 