ck=\"switchBlazerTab('radar')\">六维雷达\u003c/div>\n      \u003cdiv class=\"subtab\" data-btab=\"device\" onclick=\"switchBlazerTab('device')\">灵装绝技\u003c/div>\n      \u003cdiv class=\"subtab\" data-btab=\"roster\" onclick=\"switchBlazerTab('roster')\">同伴名册\u003c/div>\n    \u003c/div>\n    \u003cdiv class=\"body\" id=\"blazer-body\">\u003c/div>\n  \u003c/div>\n\n  \u003c!-- 3. 破军 LIME 通讯 -->\n  \u003cdiv class=\"scr\" id=\"scr-lime\">\n    \u003cdiv class=\"apphead\">\n      \u003cbutton class=\"back\" onclick=\"goBack()\">\u003ci class=\"ti ti-chevron-left\">\u003c/i>\u003c/button>\n      \u003cspan class=\"t\" id=\"lime-title\">破军 LIME\u003c/span>\n      \u003cspan class=\"sub\" id=\"lime-sub\">通讯录名册\u003c/span>\n    \u003c/div>\n    \u003cdiv class=\"body\" id=\"lime-body\">\u003c/div>\n  \u003c/div>\n\n  \u003c!-- 4. 学园圈 (Moments) -->\n  \u003cdiv class=\"scr\" id=\"scr-moments\">\n    \u003cdiv class=\"apphead\">\n      \u003cbutton class=\"back\" onclick=\"goBack()\">\u003ci class=\"ti ti-chevron-left\">\u003c/i>\u003c/button>\n      \u003cspan class=\"t\">学园圈 (Moments)\u003c/span>\n      \u003cspan class=\"act\">\u003cbutton onclick=\"postMomentPrompt()\">\u003ci class=\"ti ti-plus\">\u003c/i> 发动态\u003c/button>\u003c/span>\n    \u003c/div>\n    \u003cdiv class=\"body\" id=\"moments-body\">\u003c/div>\n  \u003c/div>\n\n  \u003c!-- 5. 破军BBS 论坛 -->\n  \u003cdiv class=\"scr\" id=\"scr-bbs\">\n    \u003cdiv class=\"apphead\">\n      \u003cbutton class=\"back\" onclick=\"goBack()\">\u003ci class=\"ti ti-chevron-left\">\u003c/i>\u003c/button>\n      \u003cspan class=\"t\">破军 BBS // 选拔战板\u003c/span>\n      \u003cspan class=\"act\">\u003cbutton onclick=\"refreshBbs()\">\u003ci class=\"ti ti-refresh\">\u003c/i> 刷新\u003c/button>\u003c/span>\n    \u003c/div>\n    \u003cdiv class=\"body\" id=\"bbs-body\">\u003c/div>\n  \u003c/div>\n\n  \u003c!-- 6. 选拔赛程 (Schedule) -->\n  \u003cdiv class=\"scr\" id=\"scr-schedule\">\n    \u003cdiv class=\"apphead\">\n      \u003cbutton class=\"back\" onclick=\"goBack()\">\u003ci class=\"ti ti-chevron-left\">\u003c/i>\u003c/button>\n      \u003cspan class=\"t\">选拔赛程与决斗\u003c/span>\n    \u003c/div>\n    \u003cdiv class=\"body\" id=\"schedule-body\">\u003c/div>\n  \u003c/div>\n\n  \u003c!-- 7. 灵装画廊 (Gallery) -->\n  \u003cdiv class=\"scr\" id=\"scr-gallery\">\n    \u003cdiv class=\"apphead\">\n      \u003cbutton class=\"back\" onclick=\"goBack()\">\u003ci class=\"ti ti-chevron-left\">\u003c/i>\u003c/button>\n      \u003cspan class=\"t\">灵装与战术相册\u003c/span>\n    \u003c/div>\n    \u003cdiv class=\"body\" id=\"gallery-body\">\u003c/div>\n  \u003c/div>\n\n  \u003c!-- 8. 学园校历 (Calendar) -->\n  \u003cdiv class=\"scr\" id=\"scr-calendar\">\n    \u003cdiv class=\"apphead\">\n      \u003cbutton class=\"back\" onclick=\"goBack()\">\u003ci class=\"ti ti-chevron-left\">\u003c/i>\u003c/button>\n      \u003cspan class=\"t\">破军学园校历\u003c/span>\n      \u003cspan class=\"sub\" id=\"calendar-sub\">2013年 · 纪日\u003c/span>\n    \u003c/div>\n    \u003cdiv class=\"body\" id=\"calendar-body\">\u003c/div>\n  \u003c/div>\n\n  \u003c!-- 9. 终端配置 (Settings) -->\n  \u003cdiv class=\"scr\" id=\"scr-settings\">\n    \u003cdiv class=\"apphead\">\n      \u003cbutton class=\"back\" onclick=\"goBack()\">\u003ci class=\"ti ti-chevron-left\">\u003c/i>\u003c/button>\n      \u003cspan class=\"t\">终端配置\u003c/span>\n    \u003c/div>\n    \u003cdiv class=\"body\" id=\"settings-body\">\u003c/div>\n  \u003c/div>\n\n\u003c/div>\n\n\u003c!-- 底部 Homebar -->\n\u003cdiv id=\"homebar\">\n\u003cbutton onclick=\"goBack()\" title=\"返回上一页\">← 返回\u003c/button>\u003cbutton onclick=\"goHome()\" title=\"返回主界面\">\u003csvg xmlns=\"http://www.w3.org/2000/svg\" class=\"\" viewBox=\"0 0 16 16\" width=\"12\" height=\"12\" fill=\"currentColor\" shape-rendering=\"crispEdges\" aria-hidden=\"true\">\u003crect x=\"7\" y=\"2\" width=\"1\" height=\"1\"/>\u003crect x=\"8\" y=\"2\" width=\"1\" height=\"1\"/>\u003crect x=\"6\" y=\"3\" width=\"1\" height=\"1\"/>\u003crect x=\"7\" y=